PRAGMA foreign_keys = ON;

CREATE TABLE source_assistance_enrolments (
    enrolment_reference TEXT PRIMARY KEY NOT NULL,
    masked_enrolment_reference TEXT NOT NULL,
    record_revision TEXT NOT NULL,
    lifecycle_state TEXT NOT NULL,
    recorded_at TEXT NOT NULL,
    programme_code TEXT NOT NULL,
    enrolment_status TEXT NOT NULL,
    valid_through TEXT,
    service_area_code TEXT NOT NULL,
    case_reference TEXT NOT NULL,
    person_reference TEXT NOT NULL
) STRICT;

