CREATE VIEW relay_assistance_enrolments AS
SELECT enrolment_reference,
       masked_enrolment_reference,
       record_revision,
       lifecycle_state,
       recorded_at,
       programme_code,
       enrolment_status,
       valid_through,
       service_area_code,
       case_reference,
       person_reference
FROM source_assistance_enrolments;
